@import url('https://fonts.googleapis.com/css2?family=DM+Mono:wght@400;500&family=DM+Sans:wght@400;500;600;700;800&family=Manrope:wght@600;700;800&display=swap');
:root{--ink:#d7e9e9;--muted:#89a7ad;--deep:#071923;--panel:#0b202b;--line:rgba(181,229,224,.13);--mint:#78e4c4;--gold:#ffcf77}*{box-sizing:border-box}html,body{margin:0;width:100%;height:100%;overflow:hidden;background:#06151e;color:var(--ink);font-family:'DM Sans',sans-serif}button{font:inherit;color:inherit;border:0;cursor:pointer}.game-shell{height:100dvh;max-height:100vh;min-height:580px;display:grid;grid-template-rows:68px minmax(0,1fr) 116px 28px;background:radial-gradient(ellipse at 50% 0,#173843,#071720 68%);padding:0 24px;gap:0;max-width:1800px;margin:auto}.topbar{display:flex;align-items:center;gap:25px;border-bottom:1px solid var(--line);position:relative;z-index:5}.brand{display:flex;align-items:center;gap:9px;color:#dcf4ec;text-decoration:none;font:800 16px Manrope,sans-serif;letter-spacing:2px}.brand-mark{display:grid;place-items:center;width:34px;height:34px;border-radius:11px;background:linear-gradient(145deg,#79e5c4,#31a9a0);color:#082e35;font-size:21px;box-shadow:0 0 22px #61d6b546}.brand small{display:block;color:#86a8aa;font:500 8px 'DM Mono';letter-spacing:2px;margin-top:1px}.profile{height:42px;border-left:1px solid var(--line);padding-left:22px;display:flex;gap:9px;align-items:center;min-width:170px}.avatar{width:32px;height:32px;border-radius:9px;display:grid;place-items:center;background:linear-gradient(145deg,#faad78,#e48688);color:#fff;font-size:19px;border:1px solid #ffd1a65c}.profile b,.location b,.weather b{font-size:11px;letter-spacing:.5px}.profile small,.location small,.weather small{display:block;font:10px 'DM Mono';color:#88a6aa;margin-top:2px}.xp{height:3px;background:#1a3a43;border-radius:3px;width:62px;margin-left:10px;overflow:hidden}.xp i{display:block;width:60%;height:100%;background:#76e3bd}.wallet{margin-left:auto;border:1px solid #9a96644f;border-radius:9px;padding:7px 12px;color:#ffdb91;display:flex;align-items:center;gap:6px;font-size:12px;background:#2c2b1d50}.wallet span{font-size:16px}.wallet small{font:8px 'DM Mono';color:#a7a48a;margin-left:3px;letter-spacing:1px}.icon-btn{width:32px;height:32px;border-radius:9px;background:#112a35;color:#a8c1be;border:1px solid var(--line)}.game-area{position:relative;min-height:260px;overflow:hidden;margin:13px 0 11px;border:1px solid #95d7cc37;border-radius:12px;background:#18384a;box-shadow:0 13px 50px #0005,inset 0 0 0 1px #ffffff08}.game-area canvas{display:block;width:100%;height:100%;image-rendering:pixelated}.scene-vignette{position:absolute;inset:0;pointer-events:none;box-shadow:inset 0 0 110px #0618266b, inset 0 -95px 65px #08212f55}.scene-topline{position:absolute;top:17px;left:19px;right:20px;display:flex;justify-content:space-between;pointer-events:none}.location,.weather{display:flex;align-items:center;gap:10px;padding:9px 12px;border:1px solid #bfebd21c;background:#0b232aa8;backdrop-filter:blur(8px);border-radius:8px}.weather{margin-left:auto}.pulse{width:8px;height:8px;background:#6be0b8;border-radius:50%;box-shadow:0 0 11px #6be0b8}.weather>span{font-size:21px;color:#ffd880}.world-actions{position:absolute;top:91px;right:18px;display:grid;gap:8px}.round-action{width:34px;height:34px;border-radius:9px;background:#09202bba;border:1px solid #bde8d82a;color:#a9d8cd;font-size:18px;backdrop-filter:blur(8px)}.scene-bottom{position:absolute;bottom:15px;left:19px;right:19px;display:flex;justify-content:space-between;align-items:center;pointer-events:none}.hint,.world-coords{font:10px 'DM Mono';letter-spacing:.2px;color:#c7e4dc;background:#0a2029b8;padding:8px 11px;border-radius:6px;border:1px solid #bde8d81b;backdrop-filter:blur(5px)}kbd{font:9px 'DM Mono';padding:3px 5px;border:1px solid #a9c8bd40;border-radius:4px;color:#c9e8d9;background:#152f36;margin-right:5px}.world-coords{color:#8eafb0;font-size:9px;letter-spacing:1px}.world-coords span{color:#69d5b2;margin:0 4px}.toast{position:absolute;left:50%;top:70px;transform:translate(-50%,-12px);background:#102d32e8;color:#b8f5d9;border:1px solid #70d7b457;border-radius:7px;padding:9px 14px;font:11px 'DM Mono';opacity:0;transition:.25s;pointer-events:none;z-index:2}.toast.show{opacity:1;transform:translate(-50%,0)}.fish-alert{position:absolute;top:50%;left:50%;transform:translate(-50%,-50%) scale(.8);padding:12px 19px;border-radius:9px;background:#fbca69ed;color:#302915;display:flex;align-items:center;gap:9px;box-shadow:0 0 35px #ffcf77a1;opacity:0;transition:.25s;pointer-events:none}.fish-alert.show{opacity:1;transform:translate(-50%,-50%) scale(1)}.fish-alert span{font-size:22px}.fish-alert b{font:800 12px Manrope;letter-spacing:1px}.fish-alert small{font:9px 'DM Mono'}.fishing-panel{display:none;position:absolute;bottom:62px;left:50%;transform:translateX(-50%);width:min(360px,90%);border:1px solid #79ddbd70;background:#09212beF;padding:12px 15px;border-radius:10px;box-shadow:0 12px 40px #0007}.fishing-panel.active{display:block}.fish-panel-top{display:flex;justify-content:space-between;color:#91e7c7;font:9px 'DM Mono';letter-spacing:.8px;margin-bottom:12px}.fish-panel-top span+span{color:#fed788}.fight-row{display:flex;align-items:center;gap:13px;margin:9px 0}.tension-label{font:8px 'DM Mono';width:112px;color:#d0e7dc}.tension-label small{display:block;color:#789b9a;margin-top:4px;font-size:7px}.tension-meter,.progress-track{height:9px;flex:1;background:#153b3e;border-radius:6px;position:relative;overflow:hidden}.tension-meter:before{content:'';position:absolute;left:36%;width:30%;top:0;bottom:0;background:#46a978;border-inline:1px solid #91e5a5}.tension-meter b{position:absolute;top:-3px;left:50%;height:15px;width:3px;background:#fff2ad;box-shadow:0 0 8px #fff3ac}.progress-track i{height:100%;display:block;width:0;background:linear-gradient(90deg,#61c59e,#a9edbc);border-radius:5px}.reel-btn{width:100%;padding:8px;margin-top:7px;border-radius:6px;background:#50bc9c;color:#082c2a;font:800 10px Manrope;letter-spacing:1px}.toolbar{display:flex;align-items:stretch;justify-content:flex-start;gap:17px;padding:10px 13px;border:1px solid var(--line);border-radius:10px;background:linear-gradient(115deg,#102630,#0b1c25);box-shadow:0 8px 25px #0002;min-height:0}.tool-group{display:flex;gap:5px;align-items:center;position:relative;padding-top:16px}.tool-caption{position:absolute;left:4px;top:-1px;color:#789799;font:8px 'DM Mono';letter-spacing:1.2px;white-space:nowrap}.tool-caption em{color:#647c7e;font-style:normal}.tool{position:relative;min-width:57px;height:67px;border:1px solid transparent;border-radius:7px;background:transparent;color:#9bb4b3;display:flex;flex-direction:column;justify-content:center;align-items:center;gap:3px;transition:.15s}.tool:hover,.tool.active{background:#1b3d42;border-color:#76d7b63d;color:#c4efdb}.tool>span{font-size:20px;line-height:24px}.tool .tool-emoji{font-size:21px}.tool small,.block-tool small,.build-toggle small{font:8px 'DM Mono';letter-spacing:.6px}.tool kbd{position:absolute;right:3px;top:3px;font-size:7px;padding:2px 3px;color:#6d9795;background:#0d252b}.count{position:absolute;right:1px;top:2px;color:#80debb;font:8px 'DM Mono';font-style:normal}.toolbar-divider{width:1px;background:var(--line);align-self:center;height:58px}.build-tools{gap:4px}.block-tool{width:55px;height:67px;border:1px solid transparent;border-radius:7px;background:transparent;color:#93acaa;display:flex;flex-direction:column;justify-content:center;align-items:center;gap:5px;position:relative}.block-tool:hover,.block-tool.selected{background:#1b393d;border-color:#78d5b746;color:#d0eadb}.block-swatch{display:block;width:20px;height:19px;border-radius:3px;border:2px solid #0003;box-shadow:inset 0 2px #ffffff36,inset 0 -3px #0003}.block-swatch.wood{background:repeating-linear-gradient(0deg,#986747 0 4px,#b17d50 4px 7px)}.block-swatch.stone{background:#71818a}.block-swatch.water{background:linear-gradient(180deg,#73d7cf 0 3px,#368da1 3px 100%)}.block-swatch.coral{background:#d77d6e}.build-toggle{height:48px;min-width:61px;margin-left:3px;border-radius:7px;background:#19353b;color:#9ab7ae;display:flex;flex-direction:column;align-items:center;justify-content:center;gap:3px;border:1px solid #a9d9c31a}.build-toggle.on{background:#36a987;color:#06312d}.build-toggle>span{font-size:19px}.build-toggle kbd{padding:1px 3px}.utility-tools{margin-left:auto}.utility-tools .tool{min-width:58px}.dot{position:absolute;right:8px;top:9px;width:5px;height:5px;background:#ffbc69;border-radius:50%}.footer{display:flex;align-items:center;justify-content:space-between;color:#59777d;font:8px 'DM Mono';letter-spacing:.8px}.footer i{font-style:normal;color:#82c4ae;margin:0 5px}.footer span:last-child{color:#75a59a}.mobile-controls{display:none}.modal-backdrop{display:none;position:fixed;inset:0;z-index:20;background:#020b10bd;backdrop-filter:blur(7px);align-items:center;justify-content:center;padding:15px}.modal-backdrop.open{display:flex}.modal{position:relative;width:min(600px,96vw);max-height:86vh;overflow:auto;background:linear-gradient(140deg,#12303a,#0b2029);border:1px solid #81d8bd4d;border-radius:13px;padding:27px;box-shadow:0 25px 100px #000a}.close-modal{position:absolute;right:13px;top:11px;background:none;color:#aac7be;font-size:23px}.modal h2{margin:0 0 5px;font:800 20px Manrope;color:#d9f3e5;letter-spacing:.6px}.modal .subtitle{margin:0 0 20px;color:#87a9a5;font:10px 'DM Mono'}.modal-grid{display:grid;grid-template-columns:repeat(2,1fr);gap:10px}.card{padding:13px;border:1px solid #a6d9cd22;border-radius:8px;background:#102a31}.card b{display:block;color:#cdebdc;font-size:12px}.card p{margin:5px 0 0;color:#91afab;font:10px/1.5 'DM Mono'}.card strong{color:#ffdc91}.modal-action{padding:10px 15px;border-radius:6px;background:#4fc29e;color:#092b2b;font:800 10px Manrope;letter-spacing:.6px;margin-top:14px}.fish-entry{display:flex;align-items:center;justify-content:space-between;padding:11px 3px;border-bottom:1px solid #ffffff0f}.fish-entry span:first-child{color:#b4d2c8;font-size:12px}.fish-entry small{display:block;color:#789995;font:9px 'DM Mono';margin-top:3px}.rarity{color:#85dfbd;font:9px 'DM Mono';text-transform:uppercase}.inventory-row{display:flex;flex-wrap:wrap;gap:7px}.inventory-item{border:1px solid #8cc9b92c;background:#112c33;border-radius:7px;padding:11px 12px;min-width:100px;color:#b7d5ca;font-size:11px}.inventory-item small{display:block;color:#79a49c;font:9px 'DM Mono';margin-top:4px}.progress-quest{height:5px;background:#214044;border-radius:5px;margin-top:8px}.progress-quest i{display:block;background:#6bd3aa;height:100%;border-radius:5px}
@media(max-width:900px){.game-shell{padding:0 12px;grid-template-rows:57px minmax(0,1fr) 105px 24px}.topbar{gap:13px}.brand{font-size:14px}.profile{padding-left:12px;min-width:130px}.xp{display:none}.toolbar{gap:8px;padding:8px}.tool{min-width:48px}.block-tool{width:45px}.build-toggle{min-width:54px}.utility-tools .tool{min-width:49px}.footer{font-size:7px}.footer span:last-child{display:none}}
@media(max-width:650px){html,body{overflow:hidden}.game-shell{min-height:0;height:100dvh;padding:0 7px;grid-template-rows:52px minmax(0,1fr) auto 21px}.brand{font-size:12px;letter-spacing:1px;gap:6px}.brand-mark{width:29px;height:29px}.brand small{font-size:7px}.topbar{gap:8px}.profile{min-width:0;border:0;padding:0;margin-left:auto}.profile .avatar{width:27px;height:27px}.profile b{font-size:10px}.profile small{font-size:8px}.wallet{padding:6px 8px;margin-left:0;font-size:10px}.wallet small{display:none}.icon-btn{width:28px;height:28px}.game-area{margin:7px 0 6px;border-radius:8px}.scene-topline{top:9px;left:8px;right:8px}.location,.weather{padding:6px 7px;gap:6px}.location b,.weather b{font-size:8px}.location small,.weather small{font-size:7px}.weather>span{font-size:16px}.world-actions{top:60px;right:8px}.round-action{width:30px;height:30px}.scene-bottom{bottom:8px;left:8px;right:8px}.hint,.world-coords{font-size:8px;padding:6px}.world-coords{font-size:7px}.toolbar{order:3;min-height:76px;height:76px;overflow-x:auto;gap:7px;padding:7px 5px;border-radius:8px;scrollbar-width:none}.toolbar::-webkit-scrollbar{display:none}.tool-group{padding-top:12px}.tool-caption{font-size:7px;top:0}.tool{height:54px;min-width:43px;gap:1px}.tool>span{font-size:17px;line-height:20px}.tool small,.block-tool small{font-size:7px}.tool kbd{display:none}.toolbar-divider{height:48px}.block-tool{height:54px;width:40px;gap:3px}.block-swatch{width:17px;height:16px}.build-toggle{height:41px;min-width:49px}.build-toggle>span{font-size:15px}.build-toggle small{font-size:7px}.utility-tools{margin-left:0}.utility-tools .tool{min-width:43px}.footer{font-size:6px;white-space:nowrap;overflow:hidden}.footer span:first-child{letter-spacing:.2px}.footer i{margin:0 2px}.mobile-controls{position:absolute;display:flex;justify-content:space-between;align-items:end;left:17px;right:17px;bottom:101px;pointer-events:none;z-index:3}.move-controls,.action-controls{display:flex;gap:8px;pointer-events:auto}.mobile-controls button{width:46px;height:46px;border-radius:50%;background:#09212bb8;border:1px solid #abe3cb55;color:#d3f0dc;font-size:18px;backdrop-filter:blur(6px);touch-action:none}.action-controls button{width:45px;height:45px}.fishing-panel{bottom:56px;padding:9px 11px}.fish-panel-top{margin-bottom:7px}.fight-row{margin:6px 0}.scene-bottom{bottom:8px}.hint{max-width:75%;white-space:nowrap}.world-coords{font-size:6px}.modal{padding:23px 17px}.modal-grid{grid-template-columns:1fr}.modal h2{font-size:17px}.inventory-item{min-width:85px}}

(() => {
  'use strict';
  const canvas = document.getElementById('game');
  const ctx = canvas.getContext('2d');
  const TILE = 32, WORLD_W = 96, WORLD_H = 24;
  const $ = id => document.getElementById(id);
  const blockDefs = {
    wood: { color:'#9a6847', solid:true, count:24 }, stone:{ color:'#71818a',solid:true,count:18 },
    water:{ color:'#398da0',water:true,count:30 }, coral:{ color:'#d77d6e',solid:false,count:8 }
  };
  const initialFish = [
    {name:'River Minnow',rarity:'Common',weight:[.1,.8],value:8,color:'#a8d7c6',bias:'small'},
    {name:'Bluegill',rarity:'Common',weight:[.3,1.8],value:12,color:'#85b5d1'},
    {name:'Silver Perch',rarity:'Common',weight:[.5,2.4],value:15,color:'#d0d5c8'},
    {name:'Small Carp',rarity:'Common',weight:[.6,3.8],value:17,color:'#d49e72'},
    {name:'Catfish',rarity:'Uncommon',weight:[1.2,8],value:29,color:'#a2a3a5'},
    {name:'Rainbow Trout',rarity:'Uncommon',weight:[.8,5.5],value:34,color:'#e08d89'},
    {name:'Golden Koi',rarity:'Rare',weight:[1,9],value:90,color:'#ffca6c'},
    {name:'Crystal Perch',rarity:'Rare',weight:[.6,4],value:105,color:'#8de3e1'},
    {name:'Shadow Bass',rarity:'Epic',weight:[2,12],value:230,color:'#a78cd1'},
    {name:'Ancient Dragonfish',rarity:'Legendary',weight:[8,32],value:850,color:'#f0a870'}
  ];
  const storageKey='aquaria-stage1-v1';
  let saved={}; try{saved=JSON.parse(localStorage.getItem(storageKey)||'{}')||{}}catch(_){saved={}};
  let state={coins:saved.coins??120, counts:{...Object.fromEntries(Object.entries(blockDefs).map(([k,v])=>[k,v.count])),...(saved.counts||{})}, inventory:saved.inventory||[], records:saved.records||{}, placed:saved.placed||{}, player:saved.player||{x:8*TILE,y:14*TILE-42}, facing:1, build:false, selected:'wood', cast:null, fishCaught:saved.fishCaught||0, day:0, cameraX:0, cameraY:0};
  const world = Array.from({length:WORLD_H},()=>Array(WORLD_W).fill(null));
  function setTile(x,y,type){if(x>=0&&x<WORLD_W&&y>=0&&y<WORLD_H)world[y][x]=type;}
  // A layered, hand-shaped cove with a broad custom-buildable pond.
  for(let x=0;x<WORLD_W;x++){
    const surface=14+(x>42?Math.min(4,Math.floor((x-42)/12)):0)+(x<4?1:0);
    for(let y=surface;y<WORLD_H;y++)setTile(x,y,y===surface?'grass':(y<surface+3?'dirt':'stone'));
  }
  for(let x=14;x<=31;x++)for(let y=10;y<14;y++)setTile(x,y,'water');
  for(let x=14;x<=31;x++){setTile(x,14,'mud');setTile(x,15,'stone');}
  // Small natural details and a starting pier.
  for(let x=7;x<=11;x++)setTile(x,13,'wood');
  for(let x=0;x<WORLD_W;x++)for(let y=0;y<WORLD_H;y++){
    const key=`${x},${y}`,val=state.placed[key]; if(val)setTile(x,y,val);
  }
  let W=800,H=480,dpr=1,last=0,elapsed=0,toastTimer=0,heldReel=false,keys={};
  const player=state.player; player.w=22;player.h=40;player.vx=0;player.vy=0;player.grounded=false;
  function save(){
    const placed={};for(let y=0;y<WORLD_H;y++)for(let x=0;x<WORLD_W;x++){const type=world[y][x];if(type&&!(y>=14+(x>42?Math.min(4,Math.floor((x-42)/12)):0)+(x<4?1:0))&&!(x>=14&&x<=31&&y>=10&&y<16)&&!(x>=7&&x<=11&&y===13))placed[`${x},${y}`]=type;}
    try{localStorage.setItem(storageKey,JSON.stringify({coins:state.coins,counts:state.counts,inventory:state.inventory,records:state.records,placed,player:{x:player.x,y:player.y},fishCaught:state.fishCaught}));}catch(_){ }
  }
  function resize(){const r=canvas.getBoundingClientRect();if(!r.width||!r.height)return;dpr=Math.min(window.devicePixelRatio||1,2);W=r.width;H=r.height;canvas.width=Math.floor(W*dpr);canvas.height=Math.floor(H*dpr);ctx.setTransform(dpr,0,0,dpr,0,0);ctx.imageSmoothingEnabled=false;}
  window.addEventListener('resize',resize);new ResizeObserver(resize).observe(canvas);resize();
  function tileAt(px,py){const x=Math.floor(px/TILE),y=Math.floor(py/TILE);return x>=0&&x<WORLD_W&&y>=0&&y<WORLD_H?world[y][x]:null;}
  function isSolid(type){return !!type&&type!=='water'&&type!=='coral';}
  function rectHits(x,y,w,h){const pts=[[x,y],[x+w-1,y],[x,y+h-1],[x+w-1,y+h-1]];return pts.some(([a,b])=>isSolid(tileAt(a,b)));}
  function movePlayer(dt){
    const left=keys.ArrowLeft||keys.KeyA||keys.touchLeft,right=keys.ArrowRight||keys.KeyD||keys.touchRight;
    const speed=180;player.vx=(right?1:0)-(left?1:0);player.vx*=speed;if(player.vx)state.facing=Math.sign(player.vx);
    player.x+=player.vx*dt;
    if(rectHits(player.x,player.y,player.w,player.h)){player.x-=player.vx*dt;const dir=Math.sign(player.vx);for(let n=0;n<Math.ceil(Math.abs(player.vx*dt));n++){if(!rectHits(player.x+dir,player.y,player.w,player.h))player.x+=dir;else break;}}
    player.vy=Math.min(650,player.vy+1200*dt);player.y+=player.vy*dt;player.grounded=false;
    if(rectHits(player.x,player.y,player.w,player.h)){
      const dir=Math.sign(player.vy);player.y-=player.vy*dt;
      for(let n=0;n<Math.ceil(Math.abs(player.vy*dt))+2;n++){if(!rectHits(player.x,player.y+dir,player.w,player.h))player.y+=dir;else{if(dir>0)player.grounded=true;player.vy=0;break;}}
    }
    player.x=Math.max(0,Math.min(WORLD_W*TILE-player.w,player.x));
  }
  function surfaceAt(x){for(let y=0;y<WORLD_H;y++)if(world[y][x]==='water'&&(!world[y-1]||world[y-1][x]!=='water'))return y;return -1;}
  function nearbyWater(){const cx=(player.x+player.w/2)/TILE,cy=(player.y+player.h)/TILE;let best=null,dist=99;for(let x=Math.floor(cx)-10;x<=Math.floor(cx)+10;x++){if(x<0||x>=WORLD_W)continue;const sy=surfaceAt(x);if(sy<0)continue;const d=Math.abs(x+.5-cx);if(d<dist&&d<9&&Math.abs(sy-cy)<8){best={x,y:sy};dist=d;}}return best;}
  function showToast(message){const t=$('toast');t.textContent=message;t.classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>t.classList.remove('show'),2100);}
  function updateHud(){ $('coins').textContent=state.coins.toLocaleString();for(const k of Object.keys(blockDefs)){const el=$(k+'Count');if(el)el.textContent=state.counts[k]??0;} }
  function castLine(){if(state.cast){if(state.cast.phase==='bite'){startFight();return;}showToast('Your line is already in the water.');return;}const water=nearbyWater();if(!water){showToast('Get closer to a water edge to cast.');return;}if(player.x<water.x*TILE)state.facing=1;else state.facing=-1;const targetX=Math.max(0,Math.min(WORLD_W*TILE,(water.x+.5)*TILE));state.cast={phase:'waiting',x:targetX,y:water.y*TILE+4,timer:3.2+Math.random()*3.5,elapsed:0,fish:null,progress:0,tension:35,pull:0};showToast('Line cast — watching the water…');}
  function chooseFish(){const roll=Math.random(),index=roll<.47?Math.floor(Math.random()*4):roll<.79?4+Math.floor(Math.random()*2):roll<.94?6+Math.floor(Math.random()*2):roll<.992?8:9;return initialFish[index];}
  function startFight(){if(!state.cast||state.cast.phase!=='bite')return;state.cast.phase='fight';state.cast.fish=chooseFish();state.cast.progress=0;state.cast.tension=40;state.cast.pull=Math.random()*6.28;$('fishKind').textContent=state.cast.fish.name.toUpperCase();$('fishAlert').classList.remove('show');$('fishingPanel').classList.add('active');showToast('Keep tension steady and reel in!');}
  function stopFishing(message){state.cast=null;$('fishAlert').classList.remove('show');$('fishingPanel').classList.remove('active');heldReel=false;if(message)showToast(message);}
